function flashHTML(){if(!flash)return `<div class="panel"><span class="module-icon purple">${icon('cards')}</span><h2 style="margin-top:18px">Explain concepts in your own words.</h2><p class="muted" style="font-size:13px">Each session contains up to 10 cards. Known cards are scheduled further ahead, while cards needing review return after 15 minutes. This is self-assessment, not an exam result.</p><button class="button" data-action="flash-start">Start reviewing ${icon('arrow')}</button></div>`;
 if(flash.index>=flash.ids.length)return `<div class="panel flash-empty">${icon('check')}<h2>${flash.ids.length?'Review session complete':'There are no cards in this group right now'}</h2><p class="muted">${flash.ids.length?`${flash.ids.length} cards reviewed; ${flash.known} marked as known.`:flash.favorites?'Star concepts in the glossary to add them to this group.':'Cards return when their scheduled review is due. You can also study from all cards.'}</p><div class="inline-buttons" style="justify-content:center"><button class="button" data-action="flash-start">Next cards</button><a class="button button-outline" href="#dictionary">Go to glossary</a></div></div>`;
 const t=C.glossary[flash.ids[flash.index]];return `<div class="flash-progress"><span>${flash.index+1} / ${flash.ids.length} cards</span><span>${flash.favorites?'Saved concepts':'Mixed review'}</span></div><button class="flash-card ${flash.revealed?'revealed':''}" data-action="flash-flip" aria-label="${flash.revealed?'Return to the front of the card':'Flip the card to see the answer'}"><span class="eyebrow">${t.category}</span><h2>${esc(t.term)}</h2>${flash.revealed?`<p>${esc(t.definition)}</p><small>${esc(t.example)}</small>`:`<p>What does this concept mean?<br>When would you use it?</p><small>Tap the card to see the answer ${icon('refresh')}</small>`}</button><div class="flash-controls"><button class="button button-outline" data-action="flash-again" ${!flash.revealed?'disabled':''}>${icon('refresh')} Needs review</button><button class="button" data-action="flash-known" ${!flash.revealed?'disabled':''}>${icon('check')} I know this</button></div><p class="tiny-note">Assess yourself after flipping the card. Known: review after 1, 3, 7, 14, or 30 days. Needs review: after 15 minutes.</p>`;
}
function gradeFlash(known){if(!flash||!flash.revealed||flash.index>=flash.ids.length)return;const id=flash.ids[flash.index],old=state.review[id]||{level:0,due:0};const level=known?Math.min(old.level+1,5):0;state.review[id]={level,due:Date.now()+(known?[1,3,7,14,30][level-1]*86400000:15*60000)};if(known)flash.known++;flash.index++;flash.revealed=false;activity('terms');render(false);}
