function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startQuiz(lesson){let pool=lesson?C.questions:C.activeQuestions;const scope=$('#quiz-scope')?.value||'all',count=Number($('#quiz-count')?.value)||5;if(lesson)pool=pool.filter(q=>q.lesson===lesson);else if(scope==='completed')pool=pool.filter(q=>state.completed.includes(q.lesson));else if(scope==='wrong')pool=pool.filter(q=>state.wrong.includes(q.id));else if(scope!=='all')pool=pool.filter(q=>findLesson(q.lesson)?.module===scope);if(!pool.length){toast(scope==='completed'?'Complete a lesson first.':scope==='wrong'?'You have no incorrect answers awaiting review yet.':'There are no questions in this area.');return;}quiz={lesson,ids:shuffle(pool).slice(0,lesson?pool.length:count).map(q=>q.id),index:0,answers:[],selected:null,finished:false};render(false);}
